/// <reference types="node" />

/**
 * Generates the OpenAPI document from the oRPC contract router.
 *
 * The document is produced by oRPC's OpenAPI generator, which understands
 * Zod 4 through `@orpc/zod/zod4`, and is published as OpenAPI 3.1.1.
 *
 * The same document is served at runtime from `/openapi.json`, generated by the
 * very same function — this script exists so the document can be inspected,
 * diffed and shipped without a build artifact in the repository.
 *
 *   tsx ./scripts/generate-openapi.ts            # JSON on stdout
 *   tsx ./scripts/generate-openapi.ts --out doc.json
 *
 * The document goes to stdout and the summary to stderr, so the output can be
 * piped into a file or a diff tool unchanged.
 */
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { generateOpenApiDocument, OPENAPI_VERSION } from '../src/lib/api/openapi';

const root = process.cwd();

const outIndex = process.argv.indexOf('--out');
const outFile = outIndex === -1 ? null : process.argv[outIndex + 1];

if (outIndex !== -1 && !outFile) {
  console.error('--out requires a file path');
  process.exit(1);
}

const document = await generateOpenApiDocument();

const body = `${JSON.stringify(document, null, 2)}\n`;

if (outFile) {
  const target = path.resolve(root, outFile);
  await writeFile(target, body);
} else {
  process.stdout.write(body);
}

const paths = Object.keys((document as { paths?: Record<string, unknown> }).paths ?? {});
const operations = paths.reduce((total, routePath) => {
  const item = (document as { paths: Record<string, Record<string, unknown>> }).paths[routePath];
  return (
    total +
    Object.keys(item).filter((method) =>
      ['get', 'post', 'put', 'patch', 'delete', 'head', 'options'].includes(method)
    ).length
  );
}, 0);

console.error(
  `Generated OpenAPI ${OPENAPI_VERSION} document with ${paths.length} paths (${operations} operations)` +
    (outFile ? ` at ${path.relative(root, path.resolve(root, outFile))}` : '')
);
